const tabId = 583778164;
const searchTerms = [
  "pesco-mediterranean",
  "mediterranean pescatarian",
  "pescatarian meal plan",
  "pescatarian keto",
  "pesco vegetarian",
  "types of pescatarian",
  "healthy pescatarian"
];

const resultsByTerm = {};

for (const term of searchTerms) {
  await tool.navigate({ tabId, url: `https://www.healthline.com/search?q1=${encodeURIComponent(term)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

  const links = await browserjs(tabId, () => {
    const items = Array.from(document.querySelectorAll("a"))
      .filter(a => {
        const p = a.closest("header, nav, footer");
        return !p && a.textContent.trim().length > 3;
      })
      .map(a => ({ text: a.textContent.trim().replace(/\s+/g, " "), href: a.href }));
    // filter to top unique links
    const seen = new Set();
    const unique = [];
    for (const item of items) {
      if (!seen.has(item.href) && item.href.includes("healthline.com/")) {
        seen.add(item.href);
        unique.push(item);
      }
    }
    return unique.slice(0, 5);
  });
  resultsByTerm[term] = links;
}

console.log("Search results summary:\n", JSON.stringify(resultsByTerm, null, 2));

